 ivBytes = java.base64DecodeToByteArray(iv);
 keyBytes = java.strToBytes(key);
 decrypted = java.createSymmetricCrypto(
    "aes/cbc/ZeroPadding", 
    keyBytes,
	   ivBytes
).decryptStr(ciphertext)
 return decrypted;
}
